"""Convert between integers 1..3999 and canonical upper-case Roman numerals such as "MCMXCIV"."""
import re

_VALUES = [
    (1000, "M"), (900, "CM"), (500, "D"), (400, "CD"),
    (100, "C"), (90, "XC"), (50, "L"), (40, "XL"),
    (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I"),
]
# Canonical form only: each place value has its own pattern, so "IIII", "IC" and "VX" do not match.
_CANONICAL = re.compile(
    r"M{0,3}(CM|CD|D?C{0,3})(XC|XL|L?X{0,3})(IX|IV|V?I{0,3})"
)


def to_roman(n):
    """Upper-case Roman numeral for n, which must be an integer from 1 to 3999."""
    if not 1 <= n <= 3999:
        raise ValueError(f"roman numerals need a value from 1 to 3999: {n}")
    out = []
    for value, letters in _VALUES:
        count, n = divmod(n, value)
        out.append(letters * count)
    return "".join(out)


def from_roman(s):
    """Integer for a canonical upper-case Roman numeral, the exact strings to_roman produces."""
    if not s or _CANONICAL.fullmatch(s) is None:
        raise ValueError(f"not a canonical roman numeral: {s!r}")
    total = 0
    for value, letters in _VALUES:
        while s.startswith(letters):
            total += value
            s = s[len(letters):]
    return total

